constexpr bool program_config_exact_keys_are_strictly_sorted() {
    for (std::size_t index = 1; index < kProgramConfigExactEntries.size(); ++index) {
        const auto left = compact::direct_bank_key(kProgramConfigExactEntries[index - 1].key);
        const auto right = compact::direct_bank_key(kProgramConfigExactEntries[index].key);
        if (!(left < right)) {
            return false;
        }
    }
    return true;
}
static_assert(program_config_exact_keys_are_strictly_sorted());
constexpr bool program_config_exact_entries_are_legal() {
    for (const auto& entry : kProgramConfigExactEntries) {
        if (!compact::legal_program_config_candidate(
                entry.key, compact::ProgramConfigCandidate{entry.program_config, entry.compute_kernel_config})) {
            return false;
        }
    }
    return true;
}
static_assert(program_config_exact_entries_are_legal());
// Every entry's recipe must be spelled with exactly the compute-kernel knobs
// its key binds; otherwise resolving that key would answer a caller with
// numerics they never asked for. See compact::entries_bind_key_compute_kernel.
constexpr bool program_config_exact_entries_bind_compute_kernel() {
    return compact::entries_bind_key_compute_kernel(kProgramConfigExactEntries);
}
static_assert(program_config_exact_entries_bind_compute_kernel());
// math_approx_mode is normalized out of the key (see normalize_key_compute_kernel).
// That is sound only while no admitted entry carries a fused activation, so every
// entry must be activation-free and carry the normalized spelling. This turns the
// runtime precondition into a build failure the moment it stops holding.
constexpr bool program_config_exact_entries_permit_math_approx_normalization() {
    return compact::entries_permit_math_approx_normalization(kProgramConfigExactEntries);
}
static_assert(program_config_exact_entries_permit_math_approx_normalization());
